#!/usr/bin/env bash
# Generates a deepstream-app config for N RTSP sources from the farm.
# Usage: ./gen_app_config.sh N [path_prefix]
#   N            stream count (1/4/8/16 for the sweep)
#   path_prefix  mediamtx path prefix (default "plate" -> plate1..plateN;
#                use "cam" for the webcam farm streams)
# Output: configs/app_<prefix><N>.txt
set -euo pipefail
N=${1:?usage: gen_app_config.sh N [path_prefix]}
PREFIX=${2:-plate}
OUT="$(dirname "$0")/configs/app_${PREFIX}${N}.txt"

{
cat <<EOF
# Generated by gen_app_config.sh $N $PREFIX — do not edit by hand.
[application]
enable-perf-measurement=1
perf-measurement-interval-sec=2

[tiled-display]
enable=0

EOF

for i in $(seq 1 "$N"); do
cat <<EOF
[source$((i-1))]
enable=1
type=4
uri=rtsp://127.0.0.1:8554/${PREFIX}${i}
latency=100
num-sources=1

EOF
done

cat <<EOF
[streammux]
gpu-id=0
live-source=1
batch-size=${N}
# Max wait to close a partial batch. 33 ms = one frame interval — mirrors
# CORDERO's "batch whatever has arrived" policy as closely as DS allows.
batched-push-timeout=33000
width=1280
height=720
enable-padding=0
nvbuf-memory-type=0

[primary-gie]
enable=1
gpu-id=0
gie-unique-id=1
config-file=pgie_plates.txt

[secondary-gie0]
enable=1
gpu-id=0
gie-unique-id=2
operate-on-gie-id=1
config-file=sgie_lprnet.txt

[osd]
enable=0

[sink0]
enable=1
type=1
sync=0
EOF
} > "$OUT"
echo "wrote $OUT"
